from datetime import date, timedelta


def _is_working_day(day, holidays):
    """True if `day` is Monday-Friday and not in `holidays`."""
    if day.weekday() >= 5:  # 5 = Saturday, 6 = Sunday
        return False
    return day not in holidays


def add_workdays(start, days, holidays=()):
    """The date `days` working days from `start`. See TASK.md."""
    # Rule 4: days must be an int; bool or any other type raises TypeError.
    if type(days) is not int:
        raise TypeError("days must be an int")

    holiday_set = set(holidays)

    if days == 0:
        # Rule 3: return start if it is a working day, else first working day after.
        if _is_working_day(start, holiday_set):
            return start
        day = start
        while True:
            day = day + timedelta(days=1)
            if _is_working_day(day, holiday_set):
                return day

    step = 1 if days > 0 else -1
    remaining = abs(days)
    day = start
    # start is never counted (rule 1 / rule 2); move step by step.
    while remaining > 0:
        day = day + timedelta(days=step)
        if _is_working_day(day, holiday_set):
            remaining -= 1
    return day


def count_workdays(first, last, holidays=()):
    """Working days from `first` to `last`, both included. See TASK.md."""
    # Rule 6: when first is after last, return negative of the symmetric count.
    if first > last:
        return -count_workdays(last, first, holidays)

    holiday_set = set(holidays)
    count = 0
    day = first
    one_day = timedelta(days=1)
    while day <= last:
        if _is_working_day(day, holiday_set):
            count += 1
        day = day + one_day
    return count
